(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞50"]=[{"q": "The half disc of radius 1 in a hallway of width 1. Does it turn the corner?", "a": "yes", "w": ["no", "only if cut in two", "only with r = 2/π"], "why": "A hallway and a shape."}, {"q": "Two quarter discs set 2r apart, a half disc of radius r removed. Its area?", "a": "π/2 + 2r − πr²/2", "w": ["π/2 + πr²", "2r", "π − r²"], "why": "Two quarter discs and a bite."}, {"q": "That area is largest at what r?", "a": "r = 2/π", "w": ["r = 1", "r = ½", "r = π/4"], "why": "Two quarter discs and a bite."}, {"q": "The largest area of that family?", "a": "π/2 + 2/π ≈ 2.2074", "w": ["π/2 ≈ 1.571", "2√2 ≈ 2.83", "2.37"], "why": "Two quarter discs and a bite."}, {"q": "At the moment a sofa has turned by π/4, it lies in what?", "a": "two strips that cross at 45°", "w": ["one strip", "a quarter disc", "the corner square"], "why": "A ceiling from one moment."}, {"q": "So every sofa has area at most?", "a": "2√2 ≈ 2.83", "w": ["π/2", "2.2074", "4"], "why": "A ceiling from one moment."}, {"q": "The shape of 18 pieces has area about?", "a": "2.21953", "w": ["2.2074", "2.37", "2.83"], "why": "Eighteen pieces."}, {"q": "The question of the largest sofa. Its accepted name?", "a": "the moving sofa problem", "w": ["the Kakeya needle problem", "the piano movers’ problem", "the Kepler conjecture"], "why": "The cellar."}];
