(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞54"]=[{"q": "Steps of width h every τ seconds. The spread stays finite and above 0 as τ shrinks exactly when?", "a": "h² is a fixed multiple of τ", "w": ["h is fixed", "h = τ", "h² = τ²"], "why": "Shrink and speed up."}, {"q": "The limit path W(t) is?", "a": "a bell of spread t", "w": ["a bell of spread t²", "fixed at 0", "even on [0, t]"], "why": "Shrink and speed up."}, {"q": "W(s) = x and W(t) = y. What is W at (s + t)/2?", "a": "(x + y)/2 plus a bell of spread (t − s)/4", "w": ["(x + y)/2 exactly, no bell", "x, the earlier value", "a bell of spread t about 0"], "why": "A path built from midpoints."}, {"q": "For a time t named in advance, the chance that W has a slope at t?", "a": "0", "w": ["1", "½", "it depends on t"], "why": "Continuous, a slope nowhere."}, {"q": "The spreading bell, step by step, obeys which rule in the limit?", "a": "u_t = ½u_xx", "w": ["u_t = u_x", "u_tt = u_xx", "u_t = 0"], "why": "The spreading bell, step by step."}, {"q": "The chance h of leaving a region through part of its edge. At each inside point it is?", "a": "the average of its four neighbours", "w": ["the largest of its neighbours", "1", "0"], "why": "Exit chances average their neighbours."}, {"q": "f has a complex slope. Δ(h ∘ f) equals?", "a": "|f′|² (Δh) ∘ f", "w": ["Δh", "f′ Δh", "0, always"], "why": "Angle-keeping maps carry the walk."}, {"q": "Fair coins on the rhombus board. The chance of a red crossing?", "a": "exactly ½", "w": ["about ⅓", "1", "0"], "why": "Crossings on a board of coins."}];
