(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞67"]=[{"q": "Adding two locks (u₁ + u₂, v₁ + v₂). What does it unlock to?", "a": "m₁ + m₂ on the clock of 2", "w": ["m₁m₂", "m₁ − m₂", "nothing"], "why": "Adding under the lock."}, {"q": "For how long does the sum unlock correctly?", "a": "while the errors stay below q/4", "w": ["for ever", "once", "while q is prime"], "why": "Adding under the lock."}, {"q": "On the whole-number lock c = pk + 2r + m, what does c₁c₂ unlock to?", "a": "m₁m₂, while |t₁t₂| < p/2", "w": ["m₁ + m₂", "nothing", "m₁, always"], "why": "Multiplying, and the errors multiply."}, {"q": "Errors of size 7 and 5, multiplied, then squared. Why does that matter past 500?", "a": "the errors multiply and soon pass the bound", "w": ["the product shrinks them", "the errors do not change", "the product only doubles them"], "why": "Multiplying, and the errors multiply."}, {"q": "When can a lock run every program?", "a": "when it runs its own unlocking plus one gate", "w": ["always, for any lock", "never, for any lock", "when it can only add"], "why": "Unlocking under the lock."}, {"q": "With shrinking, d levels of products need a clock of about?", "a": "N^(d + 2)", "w": ["N^(2^d)", "Nᵈ", "N"], "why": "Levels without refreshing."}, {"q": "Without shrinking, d levels need?", "a": "N^(2^d) or more", "w": ["N^(d + 2)", "N", "d N"], "why": "Levels without refreshing."}, {"q": "A lock that adds and multiplies locked messages. Its accepted name?", "a": "fully homomorphic encryption", "w": ["a one-time pad", "public-key signing", "a hash function"], "why": "The cellar."}];
