(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞69"]=[{"q": "A span of mass m per metre moving as X sin(πx/L). The one mass it acts as?", "a": "M = mL/2", "w": ["M = mL", "M = m/2", "M = mL²"], "why": "A deck as one way of shaking."}, {"q": "N walkers pushing at random phases. About how hard is the crowd’s push?", "a": "√N times one walker", "w": ["N times", "N² times", "no harder than one"], "why": "A walker is a push at a pace."}, {"q": "And N walkers in step?", "a": "N times one walker", "w": ["√N times", "N² times", "once"], "why": "A walker is a push at a pace."}, {"q": "A walker whose pace is within CA of the deck’s. What happens?", "a": "the walker locks a quarter turn ahead and feeds the swing", "w": ["the walker stops", "nothing", "the walker damps the swing"], "why": "Falling into step."}, {"q": "The crowd size past which the swing grows?", "a": "Nc = 4ζMΩ²/(πGC·P(Ω))", "w": ["Nc = M/G", "Nc = ζ/C", "Nc = 150, for every bridge"], "why": "The number that starts it."}, {"q": "About how many walkers started the north span?", "a": "150", "w": ["15", "1500", "2"], "why": "The number that starts it."}, {"q": "A twist pushed by wind in step with its own speed. Which pace of the wind enters?", "a": "none: only its speed U", "w": ["the twist’s own pace", "the walkers’ pace", "every pace"], "why": "A twist that pushes itself."}, {"q": "A crowd falling into step with a swaying deck. Its accepted name?", "a": "synchronous lateral excitation", "w": ["resonance fatigue", "flutter", "vortex shedding"], "why": "The cellar."}];
