(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞76"]=[{"q": "A chain of n joints, each set one of k ways. How many shapes?", "a": "kⁿ", "w": ["nᵏ", "kn", "n!"], "why": "Too many shapes to try."}, {"q": "200 joints of 3 settings give about how many shapes?", "a": "2.7 × 10⁹⁵", "w": ["600", "10²⁰", "3 × 10²⁰⁰"], "why": "Too many shapes to try."}, {"q": "Eight bridge-forming letters can pair in how many ways?", "a": "105", "w": ["8", "28", "40 320"], "why": "The letters decide."}, {"q": "2m things split into m pairs: how many ways?", "a": "(2m − 1)(2m − 3) ⋯ 3 · 1", "w": ["(2m)!", "m!", "2ᵐ"], "why": "The letters decide."}, {"q": "One shape of energy −ε against W shapes of energy 0. Its share?", "a": "1/(1 + We^(−ε/kT))", "w": ["1/W", "e^(−ε/kT)", "ε/kT"], "why": "A landscape with one deep bottom."}, {"q": "So the folded shape wins once?", "a": "ε > kT ln W", "w": ["ε > W", "ε > kT", "W < 1"], "why": "A landscape with one deep bottom."}, {"q": "Two distances, from A and from B, fix a point in the plane how far?", "a": "up to a mirror image across AB", "w": ["exactly", "not at all", "up to a turn"], "why": "A shape as a grid of distances."}, {"q": "The count of too many shapes to try. Its accepted name?", "a": "Levinthal’s paradox", "w": ["Anfinsen’s dogma", "the Ramachandran plot", "the hydrophobic effect"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞77"]=[{"q": "A graph without cycles claims what of each variable?", "a": "it depends only on its parents", "w": ["it depends on every other", "it depends on none", "it causes all others"], "why": "A reversal, drawn."}, {"q": "How do the chances of the whole come out?", "a": "as a product over parents", "w": ["as a sum over parents", "as P(x)P(y) only", "as one table"], "why": "A reversal, drawn."}, {"q": "What does doing x do to the graph?", "a": "cuts the arrows into X", "w": ["cuts the arrows out of X", "adds an arrow", "nothing"], "why": "A reversal, drawn."}, {"q": "Z blocks every side path from X to Y. What is P(y | do x)?", "a": "Σ_z P(z)P(y | x, z)", "w": ["P(y | x)", "P(y)", "Σ_z P(y | z)"], "why": "The side-path rule on four dots."}, {"q": "Two graphs share every seen chance. Can they give different effects of doing?", "a": "yes: 0.8 in one and 0.5 in the other", "w": ["no, never", "only if one has a cycle", "only for doing nothing"], "why": "What no data can tell."}, {"q": "Y = βX + U, Z moves X and is untied to U. What is β?", "a": "Cov(Z, Y)/Cov(Z, X)", "w": ["Cov(X, Y)/Var X", "Cov(Z, X)/Cov(Z, Y)", "Var Y/Var X"], "why": "A lever from outside."}, {"q": "A dot where two arrows collide. Its accepted name?", "a": "a collider", "w": ["a confounder", "a mediator", "an instrument"], "why": "The cellar."}, {"q": "Averaging over Z when it blocks every side path. Its accepted name?", "a": "the back-door adjustment", "w": ["the front-door adjustment", "regression to the mean", "collider bias"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞78"]=[{"q": "m false ideas, each tested at α. How many pass on average?", "a": "mα", "w": ["α", "m", "α/m"], "why": "Fifty false passes."}, {"q": "Each idea tested at α/m. The chance any false idea passes is at most?", "a": "α, however the tests depend", "w": ["α/m", "mα", "1"], "why": "Fifty false passes."}, {"q": "The step rule passes the first k sorted ideas, for the largest k with?", "a": "p₍ₖ₎ ≤ qk/m", "w": ["p₍ₖ₎ ≤ q", "p₍ₖ₎ ≤ q/m", "p₍ₖ₎ ≥ qk/m"], "why": "A share, not a chance."}, {"q": "For independent tests, the step rule keeps the average false share at?", "a": "m₀q/m, at most q", "w": ["q/m", "q", "m₀q"], "why": "Why the share is controlled."}, {"q": "What does the step rule control, against the split level?", "a": "a share of the passes, not the chance of any false pass", "w": ["the chance of any false pass", "the number of true ideas", "nothing"], "why": "A share, not a chance."}, {"q": "A new error ranked among n past errors. Its rank is?", "a": "any of n + 1 ranks with equal chance", "w": ["always last", "always first", "the middle"], "why": "A width from ranks."}, {"q": "A width set at the ⌈(n + 1)(1 − α)⌉-th smallest past error covers the new value with chance?", "a": "at least 1 − α", "w": ["exactly α", "at most 1 − α", "½"], "why": "A width from ranks."}, {"q": "The step rule. Its accepted name?", "a": "the Benjamini–Hochberg procedure", "w": ["the Bonferroni correction", "Holm’s method", "the Bayes factor"], "why": "The cellar."}];
